import{_ as i,C as l,o as t,c as r,j as a,a as s,b as d,w as n,E as c,a2 as g,a3 as h}from"./chunks/framework.pb1iZPmZ.js";const A=JSON.parse('{"title":"14.4 System Design: Load Balancing & Scalability","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.4-load-balancing-scaling.md","filePath":"system-design/14.4-load-balancing-scaling.md"}'),u={name:"system-design/14.4-load-balancing-scaling.md"};function p(m,e,f,y,b,x){const o=l("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a("h1",{id:"_14-4-system-design-load-balancing-scalability",tabindex:"-1"},[s("14.4 System Design: Load Balancing & Scalability "),a("a",{class:"header-anchor",href:"#_14-4-system-design-load-balancing-scalability","aria-label":'Permalink to "14.4 System Design: Load Balancing & Scalability"'},"​")],-1)),(t(),d(g,null,{default:n(()=>[c(o,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20Traffic%5B%22Incoming%20Client%20Traffic%22%5D%0A%20%20%20%20%20%20%20%20Clinicians%5B%22Clinicians%20%26%20Hospital%20Workstations%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20LoadBalancer%5B%22Layer%207%20Load%20Balancer%20(Nginx%20%2F%20AWS%20ALB)%22%5D%0A%20%20%20%20%20%20%20%20LB%5B%22Round-Robin%20%2F%20Least-Connections%20Router%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20ComputeCluster%5B%22Stateless%20Express%20App%20Cluster%22%5D%0A%20%20%20%20%20%20%20%20NodeA%5B%22Node.js%20Worker%20Instance%201%22%5D%0A%20%20%20%20%20%20%20%20NodeB%5B%22Node.js%20Worker%20Instance%202%22%5D%0A%20%20%20%20%20%20%20%20NodeC%5B%22Node.js%20Worker%20Instance%203%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SharedState%5B%22Shared%20State%20Tier%20(Eliminates%20Sticky%20Sessions)%22%5D%0A%20%20%20%20%20%20%20%20MongoCluster%5B(%22MongoDB%20Replica%20Set%3A%20Shared%20Sessions%20%26%20Employees%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Clinicians%20--%3E%20LB%0A%20%20%20%20LB%20--%3E%7CRequest%201%7C%20NodeA%0A%20%20%20%20LB%20--%3E%7CRequest%202%7C%20NodeB%0A%20%20%20%20LB%20--%3E%7CRequest%203%7C%20NodeC%0A%20%20%20%20NodeA%20%26%20NodeB%20%26%20NodeC%20%3C--%3E%20SharedState%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=h('<hr><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Load balancing distributes incoming client requests across a pool of compute instances so that no single server becomes overwhelmed, maximizing throughput, reducing latency, and eliminating Single Points of Failure (SPOFs).</p><hr><h2 id="_2-whether-and-how-this-project-uses-it" tabindex="-1">2. Whether and How THIS Project Uses It <a class="header-anchor" href="#_2-whether-and-how-this-project-uses-it" aria-label="Permalink to &quot;2. Whether and How THIS Project Uses It&quot;">​</a></h2><p>In the local development prototype, load balancing is <strong>Not Used</strong>; the app runs as a single Node process (<code>app.listen(port)</code>). However, an architectural design choice was made: <strong>the server is completely stateless regarding session memory</strong>. Because sessions are stored externally in MongoDB (<code>connect-mongo</code>), multiple Express server instances can be spun up immediately behind a load balancer without requiring complex sticky sessions.</p><hr><h2 id="_3-load-balancing-strategy-comparison-table" tabindex="-1">3. Load Balancing Strategy Comparison Table <a class="header-anchor" href="#_3-load-balancing-strategy-comparison-table" aria-label="Permalink to &quot;3. Load Balancing Strategy Comparison Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Load Balancing Algorithm</th><th style="text-align:left;">Mechanism</th><th style="text-align:left;">Pros</th><th style="text-align:left;">Cons</th><th style="text-align:left;">Fit for This Auth Portal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Round-Robin</strong></td><td style="text-align:left;">Cycles sequentially through servers ($A \\rightarrow B \\rightarrow C$)</td><td style="text-align:left;">Simple, predictable</td><td style="text-align:left;">Ignores differences in server load</td><td style="text-align:left;"><strong>High (All auth requests have similar compute cost)</strong></td></tr><tr><td style="text-align:left;"><strong>Least Connections (Chosen)</strong></td><td style="text-align:left;">Routes to server with fewest active TCP connections</td><td style="text-align:left;">Adapts dynamically to traffic spikes</td><td style="text-align:left;">Requires state tracking at LB</td><td style="text-align:left;"><strong>Recommended for production cluster</strong></td></tr><tr><td style="text-align:left;"><strong>IP Hash (Sticky Sessions)</strong></td><td style="text-align:left;">Hashes client IP to bind to a specific server instance</td><td style="text-align:left;">Keeps state local to a server</td><td style="text-align:left;">Uneven distribution; fails on proxy IPs</td><td style="text-align:left;"><strong>Unnecessary (Shared MongoDB session store eliminates sticky sessions)</strong></td></tr><tr><td style="text-align:left;"><strong>Weighted Response Time</strong></td><td style="text-align:left;">Routes to fastest responding server</td><td style="text-align:left;">Optimizes latency</td><td style="text-align:left;">Complex configuration</td><td style="text-align:left;">Overkill for lightweight auth portal</td></tr></tbody></table><hr><h2 id="_4-single-points-of-failure-spofs-remediation" tabindex="-1">4. Single Points of Failure (SPOFs) &amp; Remediation <a class="header-anchor" href="#_4-single-points-of-failure-spofs-remediation" aria-label="Permalink to &quot;4. Single Points of Failure (SPOFs) &amp; Remediation&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Component</th><th style="text-align:left;">Current SPOF Status</th><th style="text-align:left;">Failure Consequence</th><th style="text-align:left;">Production Elimination Strategy</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Node.js Process</strong></td><td style="text-align:left;">Single process on port 3000</td><td style="text-align:left;">Process crash causes complete service outage</td><td style="text-align:left;">PM2 cluster mode or Kubernetes ReplicaSet with self-healing</td></tr><tr><td style="text-align:left;"><strong>MongoDB Instance</strong></td><td style="text-align:left;">Single standalone daemon on <code>localhost:27017</code></td><td style="text-align:left;">Database crash brings down auth and sessions</td><td style="text-align:left;">Deploy a 3-node MongoDB Replica Set (1 Primary + 2 Secondaries)</td></tr><tr><td style="text-align:left;"><strong>Hosting Server</strong></td><td style="text-align:left;">Single physical/virtual machine</td><td style="text-align:left;">Machine hardware failure drops hospital access</td><td style="text-align:left;">Deploy multi-Availability Zone (AZ) auto-scaling compute groups</td></tr></tbody></table><hr><h2 id="_5-what-breaks-first-at-scale" tabindex="-1">5. What Breaks First at Scale <a class="header-anchor" href="#_5-what-breaks-first-at-scale" aria-label="Permalink to &quot;5. What Breaks First at Scale&quot;">​</a></h2><ul><li><strong>10x Load</strong>: Handled without issue.</li><li><strong>100x Load</strong>: Single Node process saturates 100% CPU on SSL and template parsing; requests queue up in OS socket buffer.</li><li><strong>1000x Load</strong>: Load balancer saturates network interface bandwidth; database connection pool limits reached.</li></ul><hr><h2 id="_6-senior-engineering-improvements" tabindex="-1">6. Senior Engineering Improvements <a class="header-anchor" href="#_6-senior-engineering-improvements" aria-label="Permalink to &quot;6. Senior Engineering Improvements&quot;">​</a></h2><ol><li>Use <strong>PM2</strong> or <strong>Kubernetes</strong> to run 1 Node process per available CPU core.</li><li>Place an <strong>AWS Application Load Balancer (ALB)</strong> or <strong>Nginx</strong> in front using the <em>Least Connections</em> algorithm.</li><li>Configure health checks (<code>GET /health</code>) so the load balancer automatically removes unhealthy instances.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Because I stored sessions in MongoDB using <code>connect-mongo</code> rather than in-memory RAM, our application servers are stateless. That means we don&#39;t need sticky sessions. We can place an Nginx or AWS load balancer in front and distribute traffic using Least Connections across any number of Node.js worker processes. If any worker crashes, health checks remove it instantly while clinicians stay logged in seamlessly.&quot;</p></blockquote>',21))])}const B=i(u,[["render",p]]);export{A as __pageData,B as default};
